import React, { useState } from 'react';
import { BrainCircuit, LogOut, Shield, User, GraduationCap, ArrowRight } from 'lucide-react';

// Import the separate dashboard components
import AdminDashboard from './AdminDashboard';
import TeacherDashboard from './TeacherDashboard';
import StudentDashboard from './StudentDashboard';

const API_URL = "http://127.0.0.1:8000";

export default function App() {
  const [user, setUser] = useState(null);
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleLogin = (role) => {
    setUser({ role, name: role.charAt(0).toUpperCase() + role.slice(1) });
  };

  const onUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    const formData = new FormData();
    formData.append('file', file);
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`${API_URL}/analyze`, { method: 'POST', body: formData });
      if (!response.ok) throw new Error("Backend connection failed.");
      const result = await response.json();
      setData(result);
    } catch (err) {
      setError("AI Engine Offline. Please ensure your Python FastAPI server is running.");
    } finally {
      setLoading(false);
    }
  };

  // Login Screen Component
  if (!user) {
    return (
      <div className="min-h-screen bg-[#020617] flex items-center justify-center p-6 text-white">
        <div className="bg-[#0f172a] p-12 rounded-[3.5rem] shadow-2xl border border-slate-800 w-full max-w-md text-center">
          <div className="bg-indigo-500/10 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-indigo-500/20">
            <BrainCircuit className="text-indigo-400 w-12 h-12" />
          </div>
          <h1 className="text-white text-4xl font-black mb-2 tracking-tighter">SUCCESS<span className="text-indigo-500">PREDICT</span></h1>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em] mb-10">AI Socioeconomic Monitor</p>
          
          <div className="space-y-3">
            {[
              { id: 'admin', label: 'Administrator', icon: <Shield size={18}/> },
              { id: 'teacher', label: 'Faculty / Teacher', icon: <User size={18}/> },
              { id: 'student', label: 'Student Portal', icon: <GraduationCap size={18}/> }
            ].map(role => (
              <button 
                key={role.id}
                onClick={() => handleLogin(role.id)}
                className="w-full py-5 px-6 bg-slate-800 hover:bg-indigo-600 text-white rounded-[1.5rem] font-bold flex items-center justify-between group transition-all"
              >
                <span className="flex items-center gap-3">{role.icon} {role.label}</span>
                <ArrowRight size={18} className="opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all" />
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Main Dashboard Shell
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans">
      <nav className="bg-white/80 backdrop-blur-md border-b sticky top-0 z-50 px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2 font-black text-2xl tracking-tighter">
          <div className="bg-indigo-600 p-2 rounded-xl text-white"><BrainCircuit size={20}/></div>
          SUCCESS<span className="text-indigo-600">PREDICT</span>
        </div>
        
        <div className="flex items-center gap-6">
          <div className="text-right">
            <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest leading-none mb-1">{user.role}</p>
            <p className="text-sm font-bold text-slate-700 leading-none">{user.name} Account</p>
          </div>
          <button 
            onClick={() => {setUser(null); setData([]);}} 
            className="bg-red-50 text-red-500 p-3 rounded-2xl hover:bg-red-100 transition-all active:scale-95"
          >
            <LogOut size={20} />
          </button>
        </div>
      </nav>

      <main className="max-w-6xl mx-auto p-8 animate-in fade-in duration-500">
        {user.role === 'admin' && (
          <AdminDashboard 
            data={data} 
            loading={loading} 
            error={error} 
            onUpload={onUpload} 
          />
        )}
        
        {user.role === 'teacher' && (
          <TeacherDashboard data={data} />
        )}
        
        {user.role === 'student' && (
          <StudentDashboard />
        )}
      </main>
    </div>
  );
}
